/// <summary>
/// Abstract class for orders to create shipment and laod
/// </summary>
abstract class METOrderShipmentLoadCreation
{
    SalesTable          salesTable;
    InventTransferTable inventTransferTable;
    METOrderTransactionType orderTransactionType;

}

Method.Source:
/// <summary>
/// Construct method to initiate the subclass
/// </summary>
/// <param name = "_orderTransactionType">Transcation type</param>
/// <param name = "_orderNum">Order number</param>
/// <returns>METOrderShipmentLoadCreation</returns>
public static METOrderShipmentLoadCreation construct(METOrderTransactionType _orderTransactionType, METOrderReference       _orderNum)
{
    METOrderShipmentLoadCreation        metOrderShipmentLoadCreation;

    if (_orderTransactionType == METOrderTransactionType::SalesOrder)
    {
        metOrderShipmentLoadCreation = new METOrderShipmentLoadCreation_SalesOrder(SalesTable::find(_orderNum));
    }
    else if (_orderTransactionType == METOrderTransactionType::TransferOrder)
    {
        metOrderShipmentLoadCreation = new METOrderShipmentLoadCreation_TransferOrder(InventTransferTable::find(_orderNum));
    }
    else
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    metOrderShipmentLoadCreation.parmOrderTransactionType(_orderTransactionType);

    return metOrderShipmentLoadCreation;
}

public METOrderTransactionType parmOrderTransactionType(METOrderTransactionType     _transactionType = ordertransactionType)
{
    ordertransactionType = _transactionType;

    return ordertransactionType;
}

/// <summary>
/// Create new shipment and load
/// </summary>
/// <param name = "_createShipment">Boolean flag</param>
/// <param name = "_skipShipmentLinesCreation">Boolean flag</param>
public WMSShipmentId createShippmentLoad(boolean       _createShipment,
                                boolean       _skipShipmentLinesCreation)
{
    METSalesOrderShipmentLoadHeader  metSalesOrderShipmentLoadHeader = this.findOrCreateOpenShipment(_createShipment);
    WMSShipmentId shipmentId;
    if (metSalesOrderShipmentLoadHeader.RecId)
    {
        if (_skipShipmentLinesCreation == false)
        {
            this.createShipmentLines(metSalesOrderShipmentLoadHeader);
        }

        info(strFmt("@MET:ShipmentUpdated", metSalesOrderShipmentLoadHeader.ShipmentId));

        this.consolidateShipmentAndUpdateLoad(metSalesOrderShipmentLoadHeader, _createShipment);
        shipmentId = metSalesOrderShipmentLoadHeader.ShipmentId;
    }

    return shipmentId;
}

/// <summary>
/// Update the Load to newly created shipments
/// </summary>
/// <param name = "_shipmentLoadHeader">Shipment load header table</param>
/// <param name = "_createNewLoad">Boolean value</param>
/// <returns>LoadId</returns>
public MetLoadId consolidateShipmentAndUpdateLoad(METSalesOrderShipmentLoadHeader       _shipmentLoadHeader, boolean    _createNewLoad)
{
    orderTransactionType = this.parmOrderTransactionType();

    InventLocationId                    inventLocation = orderTransactionType == METOrderTransactionType::SalesOrder ? _shipmentLoadHeader.Warehouse : _shipmentLoadHeader.ToWarehouse;
    METSalesOrderShipmentLoadHeader     loadHeaderTable = this.findOpenLoad(_shipmentLoadHeader.Route, _shipmentLoadHeader.ConfirmedShipDate, inventLocation);
    MetLoadId                           loadId = loadHeaderTable.LoadId;

    if (loadId == '')
    {
        if (_createNewLoad == true)
        {
            loadId = NumberSeq::newGetNum(InventParameters::numRefMetLoadID()).num();
        }
    }

    if (loadId)
    {
        METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

        update_recordset metSalesOrderShipmentLoadHeader
                setting LoadId = loadId,
                        LoadStatus = MetLoadStatus::Open
                    where metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open                                 &&
                        metSalesOrderShipmentLoadHeader.Route == _shipmentLoadHeader.Route                              &&
                        metSalesOrderShipmentLoadHeader.ConfirmedShipDate == _shipmentLoadHeader.ConfirmedShipDate      &&
                        ((orderTransactionType ==METOrderTransactionType::SalesOrder            &&
                            metSalesOrderShipmentLoadHeader.Warehouse == inventLocation)        ||
                        (orderTransactionType ==METOrderTransactionType::TransferOrder          &&
                            metSalesOrderShipmentLoadHeader.ToWarehouse == inventLocation))     &&
                        metSalesOrderShipmentLoadHeader.TransactionType == orderTransactionType;

        info(strFmt("@MET:LoadUpdated", loadId));

    }

    return loadId;
}

/// <summary>
/// Init query to find open load
/// </summary>
/// <param name = "_metRoute">Route reference</param>
/// <param name = "_confirmedDate">Confirmed ship date</param>
/// <param name = "_warehouse">Warehouse reference</param>
/// <returns>Query</returns>
public Query initFindLoadQuery(METRoute                     _metRoute,
                            SalesShippingDateConfirmed      _confirmedDate,
                            InventLocationId                _warehouse)
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds =  query.addDataSource(tableNum(METSalesOrderShipmentLoadHeader));

    qbds.addRange(fieldNum(METSalesOrderShipmentLoadHeader, Route)).value(queryValue(_metRoute));
    qbds.addRange(fieldNum(METSalesOrderShipmentLoadHeader, ConfirmedShipDate)).value(queryValue(_confirmedDate));
    qbds.addRange(fieldNum(METSalesOrderShipmentLoadHeader, LoadStatus)).value(queryValue(MetLoadStatus::Open));

    return query;
}

/// <summary>
/// Find open load
/// </summary>
/// <param name = "_metRoute">Route reference</param>
/// <param name = "_confirmedDate">COnfirmed ship date</param>
/// <param name = "_inventLocationId">Warehouse</param>
/// <returns>METSalesOrderShipmentLoadHeader</returns>
public METSalesOrderShipmentLoadHeader findOpenLoad(METRoute                        _metRoute,
                                                    SalesShippingDateConfirmed      _confirmedDate,
                                                    InventLocationId                _inventLocationId)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    Query           loadQuery = this.initFindLoadQuery(_metRoute, _confirmedDate, _inventLocationId);
    QueryRun        queryRun = new QueryRun(loadQuery);

    if (queryRun.next())
    {
        metSalesOrderShipmentLoadHeader = queryRun.get(tableNum(METSalesOrderShipmentLoadHeader));
    }

    return metSalesOrderShipmentLoadHeader;
}
